import{_ as t,C as r,o,c as s,a5 as n,E as d}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"查找偏好设置与键盘操作","description":"","frontmatter":{"title":"查找偏好设置与键盘操作","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"4691d90fd30812c78b7ffc502213c6488b6af975dbde62ed22a7f82813cc87b6","order":10},"headers":[],"relativePath":"zh/user/preferences/index.md","filePath":"zh/user/preferences/index.md","lastUpdated":1794611623000}'),i={name:"zh/user/preferences/index.md"};function l(c,e,p,h,f,u){const a=r("DemoFrame");return o(),s("div",null,[e[0]||(e[0]=n('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">查找偏好设置与键盘操作 <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;查找偏好设置与键盘操作 {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>设置应用语言，找到正确的配置区域，并顺畅使用支持的键盘操作。你需要打开桌面窗口；只有配置的服务本身需要联网时，才要求网络访问。</p><h2 id="find-the-relevant-setting" tabindex="-1">查找相关设置 <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;查找相关设置 {#find-the-relevant-setting}&quot;">​</a></h2><ol><li>打开 <strong>设置 → 常规</strong> 选择界面语言。当前选项为英语（<code>en</code>）、西班牙语（<code>es</code>）、葡萄牙语（<code>pt</code>）、法语（<code>fr</code>）、简体中文（<code>zh</code>）和日语（<code>ja</code>）。语言选择不会改变 TikTok 事件标识符或插件 API 名称。</li><li>查看常规中的更新器控件：通道、自动检查、通知，以及支持时的手动检查。自动检查是可选的。签名更新是否可用，取决于构建已发布的签名配置。</li><li>使用 <strong>账户</strong> 管理 Cloud 身份及诊断。使用 <strong>协作</strong> 配置所有者访问；宿主提供该能力时使用 <strong>团队</strong>。</li><li>打开 <strong>插件</strong> 管理插件通用偏好和各插件的设置/连接面板。插件服务凭据不应填入常规设置。</li><li>打开 <strong>自动化 → 变量</strong> 管理共用运行时值，<strong>积分</strong> 管理获取规则，<strong>叠加层</strong> 设计小组件。这些配置入口有意放在对应功能旁边。</li></ol><p>自动安装仍属实验性，并被当前发布流程的构建门控禁用。可见的自动检查偏好并不承诺自动安装。请使用文档中的<a href="./../updates.html">更新流程</a>，更换版本前做好<a href="./backups.html">备份</a>。</p><h2 id="use-supported-keyboard-controls" tabindex="-1">使用支持的键盘操作 <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;使用支持的键盘操作 {#use-supported-keyboard-controls}&quot;">​</a></h2><p>使用 Tab 和 Shift+Tab 在常规控件间移动焦点，用 Enter/空格激活已聚焦的按钮。在叠加层设计检查器中，Ctrl/Meta+Z 撤销，Ctrl/Meta+Shift+Z 或 Ctrl/Meta+Y 重做。文本输入框保留自身的撤销行为。这些是编辑器快捷键，不是全局自动化热键。</p><p>如果其他控件尚未处理 Escape，它会关闭窄屏导航抽屉。对话框和编辑器可能自行处理 Escape，包括未保存变更提示。全局热键自动化需要兼容的已安装插件及其报告的后端能力。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;预期结果、状态与恢复 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>这些设置和本地键盘交互均可使用，但不声称已完成全部无障碍或平台验收。优先使用有标签的按钮、易读的窗口尺寸；动态内容干扰阅读时，可暂停事件流滚动。设置似乎缺失时，先检查所属页面和宿主能力，再考虑重置数据。不可用控件见<a href="./troubleshooting.html">故障排查</a>，常见区别见<a href="./faq.html">常见问题</a>。</p>',11)),d(a,{scenario:"settings",locale:"zh",title:"演示：设置"})])}const m=t(i,[["render",l]]);export{g as __pageData,m as default};
